const SHELL=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f4ee"><meta name="description" content="BAYAN — evidence-first knowledge, news and live data."><link rel="canonical" href="${ORIGIN}/"><link rel="manifest" href="/manifest.json"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="ai-catalog" href="/.well-known/ai-catalog.json"><title>BAYAN | بيان — مركز المعرفة</title><link rel="stylesheet" href="/styles.css?v=${BUILD}"><script async src="https://www.googletagmanager.com/gtag/js?id=G-Y16MK39Q6X"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments)}gtag("js",new Date());gtag("config","G-Y16MK39Q6X");</script></head><body><div class="bg"></div><header class="top"><a class="brand" href="/" aria-label="BAYAN"><b>BAYAN</b><span>بيان</span></a><nav id="nav"></nav><button id="menu" class="icon">☰</button></header><aside id="drawer" class="drawer"></aside><main id="app"><section class="home fallback-home"><div class="home-copy"><span class="eyebrow">BAYAN | بيان</span><h1>المعلومة أولًا.<br><em>الدليل قبل الادعاء.</em></h1><p>مركز معرفة وأخبار وبيانات مبني على الأدلة والتحقق.</p><div class="home-actions"><a class="primary" href="/search?lang=ar">ابدأ البحث</a><a class="navbtn" href="/news?lang=ar">الأخبار</a></div></div><div class="section-grid"><a class="section-card" href="/science?lang=ar"><div><h2>علوم وفهم</h2></div><b>↗</b></a><a class="section-card" href="/technology?lang=ar"><div><h2>تقنية وذكاء اصطناعي</h2></div><b>↗</b></a><a class="section-card" href="/economy?lang=ar"><div><h2>اقتصاد ومال</h2></div><b>↗</b></a><a class="section-card" href="/politics?lang=ar"><div><h2>سياسة وشأن عام</h2></div><b>↗</b></a><a class="section-card" href="/health?lang=ar"><div><h2>صحة وطب</h2></div><b>↗</b></a><a class="section-card" href="/history?lang=ar"><div><h2>تاريخ وثقافة</h2></div><b>↗</b></a><a class="section-card" href="/people?lang=ar"><div><h2>أشخاص وسير</h2></div><b>↗</b></a><a class="section-card" href="/sports?lang=ar"><div><h2>رياضة وبيانات</h2></div><b>↗</b></a><a class="section-card" href="/travel?lang=ar"><div><h2>سفر وأماكن</h2></div><b>↗</b></a><a class="section-card" href="/art?lang=ar"><div><h2>فن وترفيه</h2></div><b>↗</b></a><a class="section-card" href="/news?lang=ar"><div><h2>أخبار موثقة</h2></div><b>↗</b></a><a class="section-card" href="/trends?lang=ar"><div><h2>اهتمام واتجاهات</h2></div><b>↗</b></a><a class="section-card" href="/prices?lang=ar"><div><h2>أسعار وبيانات مباشرة</h2></div><b>↗</b></a></div><section class="home-seo-copy"><h2>كيف يساعدك بيان على فهم المعلومات؟</h2><p>يجمع بيان بين البحث المعرفي والأخبار والبيانات المباشرة في تجربة عربية وإنجليزية. هدفه أن يساعد القارئ على فهم الموضوع وسياقه، ومعرفة ما تؤكده الأدلة وما لا يزال غير محسوم. لا ينبغي الخلط بين خبر متداول، ومعلومة أكدتها مصادر مستقلة، وتحليل يشرح دلالة الوقائع.</p><p>تعتمد جودة المعلومة على وضوح المصدر وتاريخه ومدى صلته بالموضوع. لذلك يركز بيان على التحقق من هوية المصدر، ومقارنة الأدلة عندما تتوفر، وإظهار حدود المعلومات بدل تقديم التخمين كأنه حقيقة. وقد تختلف قوة الاستنتاج بحسب نوع السؤال والبيانات المتاحة، ولهذا تظل مراجعة المصادر والسياق جزءًا أساسيًا من القراءة.</p><p>يمكنك الانتقال بين العلوم والتقنية والاقتصاد والسياسة والصحة والتاريخ والأشخاص والرياضة والسفر والفنون والأخبار والاتجاهات والبيانات الحية. اختَر اللغة المناسبة، وابحث عن الموضوع مباشرة، واستخدم صفحات المنهجية لمعرفة كيف تُقيّم الأدلة. يهدف بيان إلى تقديم محتوى واضح ومفيد، لا إلى استبدال المصادر الأصلية أو إخفاء مواطن عدم اليقين.</p><p>عند قراءة نتيجة بحث أو خبر، انتبه إلى تاريخ النشر، والجهة التي نشرت المعلومة، وما إذا كان النص يقتبس وثيقة أصلية أو ينقل عن مصدر آخر. قد تكون المعلومة صحيحة في وقتها ثم تتغير، وقد لا ينطبق مثال واحد على جميع الحالات. قارن التفاصيل المهمة مع مصدر مستقل كلما أمكن، وافصل بين الوقائع المؤكدة والتفسير والرأي. وإذا كانت الأدلة غير كافية، فالأفضل توضيح ما ينقص بدل القفز إلى نتيجة نهائية. هذه الخطوات تساعد على استخدام المعرفة بوعي، سواء كنت تبحث عن معلومة علمية أو قرار عام أو خدمة أو خبر عاجل.</p></section></section></main><footer><span>© BAYAN</span><a id="f-about" href="/about?lang=ar">عن بيان</a><a id="f-method" href="/methodology?lang=ar">المنهجية</a><a id="f-privacy" href="/privacy?lang=ar">الخصوصية</a><a id="f-terms" href="/terms?lang=ar">الشروط</a><span class="footer-credit">Created by Taha Omar</span></footer><script src="/app-20261013-01.js?v=${BUILD}" defer></script></body></html>`;
const SHELL_EN=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f4ee"><meta name="description" content="BAYAN — evidence-first knowledge, news and live data."><link rel="canonical" href="${ORIGIN}/"><link rel="manifest" href="/manifest.json"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="ai-catalog" href="/.well-known/ai-catalog.json"><title>BAYAN | Knowledge Center</title><link rel="stylesheet" href="/styles.css?v=${BUILD}"><script async src="https://www.googletagmanager.com/gtag/js?id=G-Y16MK39Q6X"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments)}gtag("js",new Date());gtag("config","G-Y16MK39Q6X");</script></head><body><div class="bg"></div><header class="top"><a class="brand" href="/" aria-label="BAYAN"><b>BAYAN</b><span>BAYAN</span></a><nav id="nav"></nav><button id="menu" class="icon">☰</button></header><aside id="drawer" class="drawer"></aside><main id="app"><section class="home fallback-home"><div class="home-copy"><span class="eyebrow">BAYAN</span><h1>Information first.<br><em>Evidence before claims.</em></h1><p>A knowledge, news and live-data center built on evidence and verification.</p><div class="home-actions"><a class="primary" href="/search?lang=en">Start searching</a><a class="navbtn" href="/news?lang=en">News</a></div></div><div class="section-grid"><a class="section-card" href="/science?lang=en"><div><h2>Science & Understanding</h2></div><b>↗</b></a><a class="section-card" href="/technology?lang=en"><div><h2>Technology & AI</h2></div><b>↗</b></a><a class="section-card" href="/economy?lang=en"><div><h2>Economy & Money</h2></div><b>↗</b></a><a class="section-card" href="/politics?lang=en"><div><h2>Politics & Public Affairs</h2></div><b>↗</b></a><a class="section-card" href="/health?lang=en"><div><h2>Health & Medicine</h2></div><b>↗</b></a><a class="section-card" href="/history?lang=en"><div><h2>History & Culture</h2></div><b>↗</b></a><a class="section-card" href="/people?lang=en"><div><h2>People & Biographies</h2></div><b>↗</b></a><a class="section-card" href="/sports?lang=en"><div><h2>Sports & Data</h2></div><b>↗</b></a><a class="section-card" href="/travel?lang=en"><div><h2>Travel & Places</h2></div><b>↗</b></a><a class="section-card" href="/art?lang=en"><div><h2>Arts & Entertainment</h2></div><b>↗</b></a><a class="section-card" href="/news?lang=en"><div><h2>Verified News</h2></div><b>↗</b></a><a class="section-card" href="/trends?lang=en"><div><h2>Interest & Trends</h2></div><b>↗</b></a><a class="section-card" href="/prices?lang=en"><div><h2>Prices & Live Data</h2></div><b>↗</b></a></div><section class="home-seo-copy"><h2>How BAYAN helps you understand information</h2><p>BAYAN brings knowledge search, news and live data together in an Arabic and English experience. It is designed to help readers understand a topic and its context, distinguish what evidence supports from what remains uncertain, and avoid confusing a circulating claim with independently confirmed information or an analysis of the facts.</p><p>Reliable information depends on the clarity, date and relevance of its sources. BAYAN therefore emphasizes checking source identity, comparing evidence when available and explaining the limits of a conclusion instead of presenting guesses as facts. Evidence can support different levels of confidence depending on the question and the data available, so context and original sources remain important parts of careful reading.</p><p>Explore science, technology, economics, politics, health, history, biographies, sports, travel, arts, verified news, trends and live data. Choose your preferred language and search directly for a topic. The methodology pages explain how evidence is evaluated. BAYAN aims to make information clearer and more useful without replacing original sources or hiding uncertainty where the evidence is incomplete.</p><p>When reading a search result or news item, check the publication date, the organization that published it and whether the text cites an original document or repeats another source. Information may have been accurate when first published and later changed, and one example does not necessarily represent every case. Compare important details with an independent source when possible, and distinguish confirmed facts from interpretation and opinion. If the evidence is incomplete, the missing information should be stated rather than replaced with a confident guess. These habits are useful for science, public decisions, services and breaking news alike.</p></section></section></main><footer><span>© BAYAN</span><a id="f-about" href="/about?lang=en">About</a><a id="f-method" href="/methodology?lang=en">Methodology</a><a id="f-privacy" href="/privacy?lang=en">Privacy</a><a id="f-terms" href="/terms?lang=en">Terms</a><span class="footer-credit">Created by Taha Omar</span></footer><script src="/app-20261013-01.js?v=${BUILD}" defer></script></body></html>`;;

